            RadioGroup.Root as ArkPart,
            {
              ...attrs,
              "aria-labelledby": hasLabel && props.id ? props.id : undefined,
              defaultValue: props.defaultValue,
              disabled: props.disabled,
              invalid: props.invalid,
              name: props.name,
