                  RadioGroup.Item as ArkPart,
                  { id: optionId, key: option.value, value: option.value },
                  () => option.label,
                );
              }),
          ),
          props.error
            ? h(Field as ArkPart, { invalid: props.invalid }, () =>
                h(Field.Error as ArkPart, null, () => props.error),
